import{_ as a,a as r,c as t,ac as i}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"证书与 TLS：变更、排障与恢复自检","description":"先交代变更和恢复条件，再按故障证据检验机制。","frontmatter":{"title":"证书与 TLS：变更、排障与恢复自检","description":"先交代变更和恢复条件，再按故障证据检验机制。","showdocs":{"topics":[{"id":"certificates","title":"证书与密钥","link":"/topics/certificates/"}],"kind":"知识专题","scope":"general","audience":"general","group":"容器与运维","seriesTitle":"证书管理：信任链、名称与轮换","summary":"先交代变更和恢复条件，再按故障证据检验机制。","status":"active","related":[{"title":"证书管理：配置 TLS 证书链与验证参数","link":"/systems/security-access/certificates/plus/practice/application","kind":"应用实践","scope":"general","audience":"general"},{"title":"证书管理：配置 TLS 证书链与验证参数 · 产品配置与操作契约至完整项目说明与依赖声明","link":"/systems/security-access/certificates/plus/practice/application-part-02","kind":"应用实践","scope":"general","audience":"general"},{"title":"证书管理：配置 TLS 证书链与验证参数 · 前置、依赖与输入至综合练习与分开的解答","link":"/systems/security-access/certificates/plus/practice/application-part-01","kind":"应用实践","scope":"general","audience":"general"},{"title":"证书与 TLS：对象、配置与机制","link":"/systems/security-access/certificates/trust-model","kind":"知识专题","scope":"general","audience":"general"}],"prev":{"text":"证书管理：配置 TLS 证书链与验证参数 · 产品配置与操作契约至完整项目说明与依赖声明","link":"/systems/security-access/certificates/plus/practice/application-part-02"},"next":false},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"证书管理：配置 TLS 证书链与验证参数 · 产品配置与操作契约至完整项目说明与依赖声明","link":"/systems/security-access/certificates/plus/practice/application-part-02"},"next":false},"headers":[],"relativePath":"systems/security-access/certificates/operations.md","filePath":"systems/security-access/certificates/operations.md"}'),s={name:"systems/security-access/certificates/operations.md"};function c(n,e,o,p,l,d){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="证书与-tls-变更、排障与恢复自检" tabindex="-1">证书与 TLS：变更、排障与恢复自检 <a class="header-anchor" href="#证书与-tls-变更、排障与恢复自检" aria-label="Permalink to &quot;证书与 TLS：变更、排障与恢复自检&quot;">​</a></h1><h2 id="part-1" tabindex="-1">到期管理、密钥轮换与吊销 <a class="header-anchor" href="#part-1" aria-label="Permalink to &quot;到期管理、密钥轮换与吊销 {#part-1}&quot;">​</a></h2><p>维护TLS 证书链前先保存预期服务名、叶子/中间证书和客户端信任锚，恢复后以实际入口证书、SAN、期限与链验证验收。具体配置见<a href="/systems/security-access/certificates/plus/practice/application#product-config">配套示例</a>。</p><h3 id="part-1-rotation" tabindex="-1">重叠信任与轮换 <a class="header-anchor" href="#part-1-rotation" aria-label="Permalink to &quot;重叠信任与轮换 {#part-1-rotation}&quot;">​</a></h3><p>轮换先准备新证书链和匹配私钥，核对名称、用途、权限与期限，再原子更新并逐节点检查实际呈现对象。CA轮换常需先分发新信任、保持重叠，再切换叶子并撤下旧根；顺序颠倒会让客户端失去信任。回退只适用于仍合规且未泄露的旧对象。</p><h3 id="part-1-inventory" tabindex="-1">证书资产与责任 <a class="header-anchor" href="#part-1-inventory" aria-label="Permalink to &quot;证书资产与责任 {#part-1-inventory}&quot;">​</a></h3><p>资产清单记录服务身份、部署位置、颁发者、序列号、到期时间、责任人及续签方式，不存私钥。一个负载均衡入口可能对应多节点和多套证书，验收不能只查一个地址。自动续签还要监测发布失败、权限和重载结果，签发成功不等于全部部署成功。</p><h3 id="part-1-exercise" tabindex="-1">练习与参考解答 <a class="header-anchor" href="#part-1-exercise" aria-label="Permalink to &quot;练习与参考解答 {#part-1-exercise}&quot;">​</a></h3><p>练习：CA轮换时，服务先切到新根签发的叶子，旧客户端还只信任旧根。会发生什么？回退到已泄露的旧私钥是否可接受？</p><details class="details custom-block"><summary>参考解答</summary><p>旧客户端可能无法建立到受信任根的路径。应先受控分发新信任，保持必要重叠，再逐节点切换叶子链并验证实际呈现，最后撤旧根。已泄露私钥不能作为回退对象；需生成新密钥、重新签发并按策略撤销/隔离，保留责任人与部署位置清单。</p></details><h2 id="part-2" tabindex="-1">名称、链路与信任校验排障 <a class="header-anchor" href="#part-2" aria-label="Permalink to &quot;名称、链路与信任校验排障 {#part-2}&quot;">​</a></h2><p>本节沿实际入口证书、SAN、期限与链验证定位失败层；先确认预期服务名、叶子/中间证书和客户端信任锚，与<a href="/systems/security-access/certificates/plus/practice/application#product-config">配套示例</a>逐项对照，再选择最小修复。</p><h3 id="part-2-issuer-error" tabindex="-1">签发链错误 <a class="header-anchor" href="#part-2-issuer-error" aria-label="Permalink to &quot;签发链错误 {#part-2-issuer-error}&quot;">​</a></h3><p>unable to get local issuer certificate提示无法找到所需颁发链，先核对服务端中间证书，再核对客户端信任锚及使用的信任库。不要通过关闭验证修复。具体HTTP客户端取证步骤仍见原HTTPS排错页，本课负责证书生命周期与身份规则，不替换旧场景。</p><h3 id="part-2-name-error" tabindex="-1">名称与过期错误 <a class="header-anchor" href="#part-2-name-error" aria-label="Permalink to &quot;名称与过期错误 {#part-2-name-error}&quot;">​</a></h3><p>certificate has expired先检查时钟与实际证书到期时间；若文件已换但错误不变，检查入口是否仍命中旧节点。名称不匹配应核对SAN、连接名和SNI，不应把IP加入本地hosts后假装已改变证书身份。不同错误可能同时存在，逐项修正并保留校验。</p><h3 id="part-2-exercise" tabindex="-1">练习与参考解答 <a class="header-anchor" href="#part-2-exercise" aria-label="Permalink to &quot;练习与参考解答 {#part-2-exercise}&quot;">​</a></h3><p>练习：两个节点轮流报unable to get local issuer certificate和certificate has expired，仓库文件却已更新。各应采集什么，而不是关闭验证？</p><details class="details custom-block"><summary>参考解答</summary><p>链错误节点收集实际对外发送的叶子/中间链及客户端所用信任库；过期节点收集实际序列号、notAfter和客户端时钟。对照节点/入口路由判断是否仍命中旧证书，名称错误再核SAN、预期名称与SNI。文件更新或单节点成功不证明全入口已发布。</p></details><h2 id="part-3" tabindex="-1">证书更新后部分客户端失败的复盘 <a class="header-anchor" href="#part-3" aria-label="Permalink to &quot;证书更新后部分客户端失败的复盘 {#part-3}&quot;">​</a></h2><p>以下演练将TLS 证书链的变更、失败证据和恢复验收串起来；先熟悉<a href="/systems/security-access/certificates/plus/practice/application#product-config">配套示例</a>中的预期服务名、叶子/中间证书和客户端信任锚。演练未执行。</p><h3 id="part-3-incident-scenario" tabindex="-1">故障场景与影响 <a class="header-anchor" href="#part-3-incident-scenario" aria-label="Permalink to &quot;故障场景与影响 {#part-3-incident-scenario}&quot;">​</a></h3><p>证书文件已更新，一部分客户端仍报告校验失败。</p><p>先记录首次异常时间、受影响对象和最近变更，区分个别对象失败与整条管理链路异常。以下是排查演练，不是已发生事故的实测记录。</p><h3 id="part-3-incident-evidence" tabindex="-1">按证据定位原因 <a class="header-anchor" href="#part-3-incident-evidence" aria-label="Permalink to &quot;按证据定位原因 {#part-3-incident-evidence}&quot;">​</a></h3><ol><li>从实际域名与入口观察返回证书，核对 SNI、SAN、有效期和系统时间，不只检查磁盘文件。</li><li>检查服务端发送的中间证书与客户端信任锚，区分名称错误、过期和无法构建信任链。</li><li>核对所有实例的证书序列号、配置路径与加载状态，检查是否遗漏负载均衡或代理终止层。</li></ol><h3 id="part-3-incident-recovery" tabindex="-1">恢复步骤与验收 <a class="header-anchor" href="#part-3-incident-recovery" aria-label="Permalink to &quot;恢复步骤与验收 {#part-3-incident-recovery}&quot;">​</a></h3><p>修正具体入口的证书链或加载配置，再按服务约定重载。私钥泄露时执行换钥与吊销流程，不回退到已泄露私钥，也不关闭客户端校验。</p><p>验收：代表性客户端通过正确名称完成验证，所有入口返回预期证书，错误名称或不可信链仍被拒绝；同时确认下次到期告警和轮换责任人。</p><p>将触发条件、直接原因、修复动作、恢复证据和后续检查写入同一份复盘，明确每项后续工作的负责人。机制参考：<a href="https://docs.openssl.org/3.0/man1/openssl-verification-options/" target="_blank" rel="noopener noreferrer">官方说明</a>。</p><h3 id="part-3-check" tabindex="-1">机制自检 <a class="header-anchor" href="#part-3-check" aria-label="Permalink to &quot;机制自检 {#part-3-check}&quot;">​</a></h3><p>自检：根据上面的场景画出故障链，标出每一项证据来自哪个对象、发生在哪个时间。说明恢复动作改变了什么，以及为什么其他原本允许或拒绝的操作仍符合预期。</p><h3 id="part-3-answers" tabindex="-1">参考解答与误区 <a class="header-anchor" href="#part-3-answers" aria-label="Permalink to &quot;参考解答与误区 {#part-3-answers}&quot;">​</a></h3><p>问题一：服务器发送根证书，是否让不信任该CA的客户端自动信任？</p><p>答案：不会。信任锚来自客户端已有信任策略；服务端应提供叶子和必要中间证书，不能靠多发一个根来建立信任。</p><p>问题二：证书SAN只有db.example.invalid，通过IP访问为何可能失败？</p><p>答案：客户端期望的是IP身份时需要对应IP标识；DNS解析到同一IP不等于名称匹配，SNI选择证书也不替代校验名称。</p><p>问题三：已续签仍报过期，先查什么？</p><p>答案：核对客户端时钟与实际入口呈现的序列号和期限，再检查多节点发布与重载。磁盘新文件不证明所有进程已切换。</p><h3 id="part-3-acceptance" tabindex="-1">验收与未验证项 <a class="header-anchor" href="#part-3-acceptance" aria-label="Permalink to &quot;验收与未验证项 {#part-3-acceptance}&quot;">​</a></h3><p>验收应覆盖正常操作、预期拒绝和恢复后的再次操作，并记录实际版本、身份、配置及结果。本文示例未执行；配置审阅与离线推演不能替代真实环境的连通、权限和恢复验证。</p><h3 id="part-3-sources" tabindex="-1">版本、来源与进一步阅读 <a class="header-anchor" href="#part-3-sources" aria-label="Permalink to &quot;版本、来源与进一步阅读 {#part-3-sources}&quot;">​</a></h3><p>核对日期：2026-10-17。教学版本族：X.509/RFC5280、RFC9525和OpenSSL3.x概念；离线元数据不作密码学验证。固定源码用于重现字段，动态官方网页用于补充说明，不称为2026最新版本。具体字段与语义以本节所列一手资料及目标版本手册为准。</p><ul><li><a href="https://www.rfc-editor.org/info/rfc5280/" target="_blank" rel="noopener noreferrer">RFC5280路径与约束</a></li><li><a href="https://www.rfc-editor.org/rfc/rfc9525.html" target="_blank" rel="noopener noreferrer">RFC9525服务身份</a></li><li><a href="https://curl.se/docs/sslcerts.html" target="_blank" rel="noopener noreferrer">curl证书校验</a></li><li><a href="https://docs.openssl.org/3.0/man1/openssl-verification-options/" target="_blank" rel="noopener noreferrer">OpenSSL3.0验证说明</a></li></ul>',44)])])}const f=a(s,[["render",c]]);export{u as __pageData,f as default};
